insert into daraja.quotes (id, kind, body, author, active) values
(1, 'proverbe', 'Goutte après goutte, la rivière se forme.', 'Proverbe marocain', true),
(2, 'proverbe', 'Celui qui sert les autres ne s''appauvrit jamais.', 'Proverbe arabe', true),
(3, 'proverbe', 'La patience est la clé du soulagement.', 'Proverbe arabe', true),
(4, 'proverbe', 'Un invité est un cadeau de Dieu.', 'Proverbe de l''hospitalité orientale', true),
(5, 'proverbe', 'Seul on va plus vite, ensemble on va plus loin.', 'Proverbe africain', true),
(6, 'proverbe', 'Le chemin est long, mais il commence par un pas.', 'Proverbe', true),
(7, 'proverbe', 'Celui qui sème le sourire récolte la fidélité.', 'Proverbe de salle', true),
(8, 'citation', 'L''hospitalité est un dialogue, le service est un monologue.', 'Danny Meyer', true),
(9, 'proverbe', 'Un sourire coûte moins cher que l''électricité, mais donne autant de lumière.', 'Proverbe', true),
(10, 'citation', 'Les gens oublieront ce que tu as dit, mais jamais ce que tu leur as fait ressentir.', 'Attribuée à Maya Angelou', true),
(11, 'citation', 'La qualité n''est jamais un accident.', 'Attribuée à John Ruskin', true),
(12, 'citation', 'Le succès, c''est tomber sept fois et se relever huit.', 'Proverbe japonais', true),
(13, 'histoire', 'En 1806, un journal de l''État de New York publie l''une des premières définitions du mot « cocktail » : alcool, sucre, eau et bitters.', 'Mini-histoire', true),
(14, 'histoire', 'Le Baromètre a ouvert en 2016, derrière une porte sans enseigne. Ceux qui la trouvent ne l''oublient pas.', 'Notre histoire', true),
(15, 'histoire', 'En 1919, à Florence, le comte Negroni demande un Americano plus fort. Le barman remplace l''eau gazeuse par du gin. Un classique est né.', 'Mini-histoire', true),
(16, 'histoire', 'Churchill adorait Marrakech. Il y peignait, y réfléchissait et l''a décrite comme le plus bel endroit du monde.', 'Mini-histoire', true),
(17, 'histoire', 'Le safran de Taliouine se récolte fleur par fleur, à la main, à l''aube. Il faut plus de 100 000 fleurs pour un seul kilo.', 'Mini-histoire', true),
(18, 'histoire', 'Jimi Hendrix a séjourné au Maroc en 1969. Le Baromètre lui dédie un cocktail au poivre noir.', 'Mini-histoire', true),
(19, 'histoire', 'Le mot « mixologie » existe depuis le XIXe siècle. Ce que tu fais au comptoir a une longue histoire.', 'Mini-histoire', true),
(20, 'histoire', 'Zama Zama est née sous le signe du serpent, qui veille sur ce qui est précieux. Ce soir, le précieux, c''est le client.', 'Notre histoire', true),
(21, 'motivation', 'Chaque table est une scène. Ce soir, tu es la star.', null, true),
(22, 'motivation', 'Un client qui revient, c''est la plus belle des récompenses.', null, true),
(23, 'motivation', 'Personne ne naît expert. Tout le monde le devient, une question à la fois.', null, true),
(24, 'motivation', 'Aujourd''hui, retiens un prénom de client. Demain, il reviendra pour toi.', null, true),
(25, 'motivation', 'Les petits détails font les grands souvenirs.', null, true),
(26, 'motivation', 'Ta série te regarde. Ne la laisse pas s''éteindre.', null, true),
(27, 'motivation', 'Un bon service se voit. Un grand service se ressent.', null, true),
(28, 'motivation', 'Aujourd''hui, raconte l''histoire d''un cocktail à au moins une table.', null, true),
(29, 'motivation', 'Le rush passe. La bonne impression reste.', null, true),
(30, 'motivation', 'Sois la raison pour laquelle quelqu''un sourit ce soir.', null, true),
(31, 'motivation', 'L''équipe, c''est comme un cocktail : chaque ingrédient compte.', null, true),
(32, 'motivation', 'Tu as appris quelque chose hier. Aujourd''hui, on monte d''une marche.', null, true),
(33, 'motivation', 'Daraja veut dire « marche » : une marche par jour, et tu arrives en haut.', null, true),
(34, 'motivation', 'Ton prochain cadeau est peut-être à un quiz près.', null, true),
(35, 'encouragement', 'Tu peux être fier de ce que tu fais chaque soir.', null, true),
(36, 'encouragement', 'Même les meilleurs bartenders ont cassé des verres.', null, true),
(37, 'encouragement', 'Une erreur rattrapée avec le sourire vaut mieux qu''un service parfait sans âme.', null, true),
(38, 'encouragement', 'Respire, souris, et laisse la soirée commencer.', null, true),
(39, 'encouragement', 'Ce soir, tu ne sers pas des plats. Tu crées des souvenirs.', null, true),
(40, 'encouragement', 'Aide un collègue aujourd''hui. Il s''en souviendra.', null, true)
