insert into daraja.questions (id, venue, theme, question, options, answer_idx, explanation, active, level, kind, payload, cat) values
('2b234e47-4efc-4d83-8bb1-5c488d792b50', null, 'English', 'Propose ton cocktail signature en anglais', '[]', 0, 'La formule polie par excellence : « May I… ».', true, 1, 'order', '{"answer": ["May", "I", "recommend", "our", "signature", "cocktail", "?"]}', 'anglais'),
('2cb6259a-3b93-47c9-afd1-57fa55e981d0', null, 'Anglais en images', 'En anglais, une crevette se dit…', '["A prawn (ou shrimp)", "A crab", "A lobster", "A squid"]', 0, 'Prawn ou shrimp = crevette. Lobster = homard.', true, 1, 'image', '{"img": "ef1f8ff69f82"}', 'anglais'),
('3fdae597-0e62-4101-8082-a55c3dca4b6a', null, 'English', '« L''addition, s''il vous plaît » : le client anglais dit…', '["The count, please", "The note, please", "The bill, please", "The addition, please"]', 2, '« Bill » en Angleterre, « check » aux États-Unis.', true, 1, 'qcm', null, 'anglais'),
('429b0a41-c4ff-4190-8e61-5164ffb5e4d1', null, 'Anglais en images', 'En anglais, ce fruit se dit…', '["Cherry", "Raspberry", "Blueberry", "Strawberry"]', 3, 'Strawberry = fraise. Raspberry = framboise.', true, 1, 'image', '{"img": "410e9867b280"}', 'anglais'),
('43c54f52-d15e-43e2-b5bb-e5536f713a5c', null, 'Anglais en images', 'En anglais, ce fruit se dit…', '["Lemon", "Orange", "Grapefruit", "Lime"]', 0, 'Lemon = citron jaune. Lime = citron vert.', true, 1, 'image', '{"img": "1192b8967623"}', 'anglais'),
('608eee6a-b91f-4c94-a165-fabc60648124', null, 'Anglais en images', 'En anglais, ça se dit…', '["Garlic", "Leek", "Ginger", "Onion"]', 0, 'Garlic = ail. Onion = oignon. Leek = poireau.', true, 1, 'image', '{"img": "f668c306a2bd"}', 'anglais'),
('6aa9d281-0b45-4fbe-bb5b-95b03449c99f', null, 'Anglais en images', 'En anglais, ce fruit se dit…', '["Avocado", "Lawyer", "Pear", "Olive"]', 0, 'Avocado ! « Lawyer », c''est l''avocat… au tribunal.', true, 1, 'image', '{"img": "f948be2c0d8e"}', 'anglais'),
('8eaba602-432c-4f22-b047-a651d4cf5f46', null, 'English', 'Comment dire « Bon appétit » à un client anglophone ?', '["Have a good food", "Enjoy your meal", "Good appetite", "Eat well"]', 1, '« Enjoy your meal » est la formule naturelle.', true, 1, 'qcm', null, 'anglais'),
('a450fc55-eed2-493d-ae9c-cbfd88b3615d', null, 'English', 'Demande les allergies', '[]', 0, 'Une question à poser à chaque table, en anglais comme en français.', true, 1, 'order', '{"answer": ["Do", "you", "have", "any", "food", "allergies", "?"]}', 'anglais'),
('d4bd6ca2-16e7-48ef-89b9-844a5162a7e5', null, 'English', '« Je reviens tout de suite » se dit…', '["I''m coming back soon", "I come back now", "I''ll be right back", "I return quickly"]', 2, 'Court, poli, naturel.', true, 1, 'qcm', null, 'anglais'),
('d785ba34-39f2-4377-9659-1e6e3cefb4a0', null, 'English', '« Prenez votre temps » en anglais :', '["Have your time", "Take your time", "Make your time", "Take the time"]', 1, '« Take your time, I''ll come back in a minute. »', true, 1, 'qcm', null, 'anglais'),
('dcff21d0-8016-4f06-8d5b-608e369d845b', null, 'English', 'Propose l''eau', '[]', 0, 'Still = plate, sparkling = pétillante.', true, 1, 'order', '{"answer": ["Would", "you", "like", "still", "or", "sparkling", "water", "?"]}', 'anglais'),
('e6cb9288-e580-46e8-8fe2-baf33dd40671', null, 'Anglais en images', 'Un client demande « Is it spicy? ». Il veut savoir si c''est…', '["Cher", "Froid", "Sucré", "Épicé, pimenté"]', 3, 'Spicy = épicé. Tu peux répondre : « Just a little » ou « Not at all ».', true, 1, 'image', '{"img": "d9964e08be09"}', 'anglais'),
('ff8075b8-cff7-47e1-a6c0-b10973d3e93b', null, 'Associations', 'Relie le français à l''anglais', '[]', 0, 'Les mots qu''on entend tous les soirs.', true, 1, 'match', '{"pairs": [["Agneau", "Lamb"], ["Poulpe", "Octopus"], ["Loup bar", "Sea bass"], ["Gambas", "Prawns"]]}', 'anglais'),
('0294a61b-0c0a-449f-a898-e77154609c9e', null, 'English', 'Quelle phrase est correcte ?', '["I''m agree", "I am agree with you", "I agree with you", "I agreed with you now"]', 2, 'Erreur très fréquente : on ne dit jamais « I am agree ».', true, 2, 'qcm', null, 'anglais'),
('31948391-82d7-44fd-82a9-72c7d4f656c3', null, 'Anglais en images', 'En anglais, le calamar se dit…', '["Octopus", "Shrimp", "Oyster", "Squid"]', 3, 'Squid = calamar. Octopus = poulpe.', true, 2, 'image', '{"img": "ca691820e935"}', 'anglais'),
('43101bde-c7e6-404b-9d3d-72bf5269301e', null, 'English', 'Propose le dessert', '[]', 0, 'Le moment idéal : quand tu débarrasses les assiettes.', true, 2, 'order', '{"answer": ["Would", "you", "like", "to", "see", "the", "dessert", "menu", "?"]}', 'anglais'),
('608d3fb1-a5a6-4308-a843-e16d357f0b15', null, 'English', 'Annonce l''attente de la table', '[]', 0, 'Un délai honnête rassure le client.', true, 2, 'order', '{"answer": ["Your", "table", "will", "be", "ready", "in", "five", "minutes", "."]}', 'anglais'),
('7ccc72b7-5306-43df-84bc-7bdb1b4b4042', null, 'English', '« Loup bar » en anglais :', '["Bar fish", "Sea bream", "Sea bass", "Sea wolf"]', 2, 'Sea bass. La daurade, elle, se dit sea bream.', true, 2, 'qcm', null, 'anglais'),
('8174f026-fd18-455c-9470-7cba5dd83c75', null, 'English', '« Effiloché de bœuf » en anglais :', '["Pulled cow", "Shredded cow", "Torn beef", "Pulled beef"]', 3, '« Pulled » : comme le célèbre pulled pork.', true, 2, 'qcm', null, 'anglais'),
('c2fd6667-2aed-4d69-8b22-62ef618916ed', null, 'English', '« Citron confit » en anglais :', '["Pickled orange", "Confit lemon", "Candied lemon", "Preserved lemon"]', 3, 'Preserved lemon : un classique de la cuisine marocaine.', true, 2, 'qcm', null, 'anglais'),
('daacd920-acae-4a91-9e9e-3a7b2c8fe16d', null, 'English', 'Propose une autre tournée', '[]', 0, '« Round » = une tournée pour toute la table.', true, 2, 'order', '{"answer": ["Can", "I", "get", "you", "another", "round", "?"]}', 'anglais'),
('f0ef7962-2431-433f-a302-a67da1e4478c', null, 'Associations', 'Relie chaque formule polie à sa traduction', '[]', 0, 'La politesse, la base.', true, 2, 'match', '{"pairs": [["Prenez votre temps", "Take your time"], ["Je reviens tout de suite", "I''ll be right back"], ["Santé !", "Cheers!"], ["Bon appétit", "Enjoy your meal"]]}', 'anglais'),
('41d41410-80df-4866-9e28-c1d2208b4b2c', null, 'English', 'Le client demande « Is the octopus grilled? ». Il parle du…', '["Gambas", "Calamar", "Poisson du jour", "Poulpe"]', 3, 'Octopus = poulpe, squid = calamar, prawns = gambas.', true, 3, 'qcm', null, 'anglais'),
('868d6384-086e-47d8-ac39-90bc13a8102d', null, 'English', '« Cèpes » en anglais :', '["Truffles", "Morels", "Porcini mushrooms", "Button mushrooms"]', 2, 'Le nom italien porcini est utilisé en anglais.', true, 3, 'qcm', null, 'anglais'),
('e06075e4-0aea-478d-b6e7-a7305b1d539f', null, 'English', 'Dis au revoir comme un pro', '[]', 0, 'Chaleureux et simple.', true, 3, 'order', '{"answer": ["Thank", "you", "for", "coming", ",", "we", "hope", "to", "see", "you", "again", "soon", "!"]}', 'anglais'),
('eca05879-b4fb-4711-9247-b07aeae64f42', null, 'English', 'Demande un avis Google avec élégance', '[]', 0, 'Une demande douce, jamais insistante.', true, 3, 'order', '{"answer": ["If", "you", "enjoyed", "your", "evening", ",", "a", "Google", "review", "would", "mean", "a", "lot", "to", "us", "."]}', 'anglais'),
('0e0a420e-82c2-4cf1-84fb-586a47a92464', null, 'Caisse', 'Chaque produit servi doit avoir un bon ou un ticket enregistré.', '["Vrai", "Faux"]', 0, 'Vrai ! Un produit servi sans ticket est une faute dans la charte.', true, 1, 'tf', null, 'caisse'),
('17b25d69-9b61-4959-9fd0-1a0f729e0e5b', null, 'Caisse', 'Comment rendre la monnaie ?', '["En comptant devant le client", "En arrondissant à mon avantage", "Sans la compter", "En la posant vite sur la table"]', 0, 'Compter devant le client évite les litiges.', true, 1, 'qcm', null, 'caisse'),
('9ce0fb5d-6554-4db8-9293-c5209e634809', null, 'Stock', 'La règle FIFO à la réserve, c''est…', '["Premier entré, premier sorti", "Le plus cher d''abord", "Au hasard", "Le plus récent d''abord"]', 0, 'On place les nouveaux produits derrière les anciens.', true, 1, 'qcm', null, 'caisse'),
('a710ed67-be36-4121-a32b-a5cc72435f81', null, 'Caisse en images', 'Un client demande l''addition. Tu remets…', '["Le ticket d''une autre table", "Rien, tu annonces le total", "Un papier écrit à la main", "Le ticket édité par la caisse"]', 3, 'Chaque produit servi doit passer en caisse et figurer sur le ticket.', true, 1, 'image', '{"img": "a6d12ba0ad63"}', 'caisse'),
('ee125808-aa33-4656-8ff7-ef1f71daecbd', null, 'Caisse en images', 'Paiement par carte : le client…', '["Donne son code au serveur", "Laisse sa carte au bar", "Signe un papier vierge", "Garde sa carte en vue et tape son code seul"]', 3, 'Le code est secret : on tourne le terminal vers le client.', true, 1, 'image', '{"img": "57c1aeeda712"}', 'caisse'),
('f95b1fa1-02e8-450e-8298-83409f318a3c', null, 'Caisse', 'Il manque de l''argent dans ta caisse en fin de service. Tu…', '["Le caches jusqu''à demain", "Modifies le ticket", "Le signales tout de suite au responsable", "Complètes de ta poche sans rien dire"]', 2, 'Un écart signalé se comprend. Un écart caché devient une faute grave.', true, 1, 'qcm', null, 'caisse'),
('1a497887-e4b2-4d61-b2ef-a2706488aa31', null, 'Caisse', 'Qui peut annuler un ticket déjà encaissé ?', '["Le responsable, après validation", "Le client", "Personne ne le vérifie", "N''importe quel serveur"]', 0, 'Une annulation sans validation est une faute grave.', true, 2, 'qcm', null, 'caisse'),
('53c93166-5479-4ff5-b126-5cde8fa43337', null, 'Achats', 'Tu ramènes du poisson frais du marché. Comment le transportes-tu ?', '["Peu importe", "Dans une glacière ou un sac isotherme, et directement au froid", "Dans un sac plastique au soleil", "Dans le coffre toute la journée"]', 1, 'La chaîne du froid commence dès l''achat.', true, 2, 'qcm', null, 'caisse'),
('6d77722d-6421-4b94-94de-fa4131f967cc', null, 'Stock', 'À la réception d''une livraison, avant de signer, tu vérifies…', '["Quantités, prix, dates limites, température et état", "Seulement le nombre de cartons", "Uniquement la facture", "Rien, le livreur est pressé"]', 0, 'Une fois signé, il est trop tard pour réclamer.', true, 2, 'qcm', null, 'caisse'),
('b429103a-9fb4-4d4c-bb1b-2506465b745a', null, 'Caisse', 'Un billet te paraît suspect. Tu…', '["Le déchires", "L''acceptes pour ne pas vexer", "Vérifies le filigrane et le fil de sécurité, refuses poliment et préviens le responsable", "Accuses le client"]', 2, 'On reste courtois : le client peut être de bonne foi.', true, 2, 'qcm', null, 'caisse'),
('c19e7bcf-bd24-46d8-86da-6d629ca5d4d9', null, 'Achats', 'Quand tu fais un achat pour l''établissement, tu rapportes toujours…', '["Juste la monnaie", "Rien, on te fait confiance", "La facture ou le ticket au nom de la société", "Une photo du magasin"]', 2, 'Sans pièce justificative, la dépense ne peut pas être comptabilisée.', true, 2, 'qcm', null, 'caisse'),
('511170ca-5367-47b8-ac14-9d88001423ef', null, 'Caisse', 'Le « Z » de caisse, c''est…', '["Une remise client", "Le code de la caisse", "Un ticket annulé", "Le rapport de clôture qui récapitule les ventes de la journée"]', 3, 'Il sert à contrôler les recettes chaque soir.', true, 3, 'qcm', null, 'caisse'),
('76b78306-8696-41aa-bbb4-6b0ff7f25e31', null, 'Stock', 'Un cocktail coûte 25 DH en ingrédients et se vend 125 DH. Son coût matière est de…', '["50 %", "25 %", "80 %", "20 %"]', 3, '25 ÷ 125 = 0,20, soit 20 %.', true, 3, 'qcm', null, 'caisse'),
('ec050d28-c83c-43ce-b109-5f86cf1b9d6e', null, 'Stock', 'À quoi sert l''inventaire ?', '["Comparer le stock théorique et le stock réel pour détecter les écarts", "Ranger la réserve", "Commander au hasard", "Compter les clients"]', 0, 'Un écart révèle une perte, une casse ou une erreur de saisie.', true, 3, 'qcm', null, 'caisse'),
('20f7706c-ea17-430a-a7e8-1b12e8acc29a', 'zz', 'Plats Zama', 'Quelle sauce accompagne le Tawouk ?', '["Harissa", "Toum (sauce à l''ail)", "Tahiné", "Chermoula"]', 1, 'Poulet mariné en brochette, sauce toum, tuiles de pita et riz au curry.', true, 1, 'qcm', null, 'carte'),
('236c9f68-ee1c-4c02-aeac-289d83ad0650', 'zz', 'À partager', 'Avec quoi est servie la Burrata Beldi ?', '["Jambon", "Salade César", "Pain beurré", "Tartare de tomates, olives noires, pesto de pignons et mélasse de grenade"]', 3, '170 DH le soir, 150 DH en terrasse.', true, 1, 'qcm', null, 'carte'),
('2c00c5af-6458-43c0-ba32-2993ee4725ee', 'baro', 'Plus ou moins', 'Lequel est le plus cher ?', '["Le Churchill", "Le Mooja"]', 0, 'Churchill 175 DH, Mooja 160 DH.', true, 1, 'price', null, 'carte'),
('6825919e-aefa-44b1-b801-756399f21e5e', 'zz', 'Terrasse', 'En terrasse, quel milk-shake est 100 % marocain ?', '["Vanille", "Fraise", "Chocolat", "Corne de Gazelle"]', 3, 'Le milk-shake Corne de Gazelle, 65 DH : parfait à raconter aux touristes.', true, 1, 'qcm', null, 'carte'),
('6fe95bbd-cc78-4823-936d-3e220cfb7fae', 'baro', 'Expérience Baro', 'À quelle heure a lieu la Mixology Class ?', '["À minuit", "Sur demande à 22h", "Le dimanche midi", "Tous les jours de 17h à 18h"]', 3, 'Minimum 2 personnes, selon disponibilité : de la théorie à la pratique avec nos mixologues.', true, 1, 'qcm', null, 'carte'),
('95450dad-e0e7-4324-9e18-c1c29ff9332a', 'zz', 'À partager', 'Les Briouates Thalata sont farcies de…', '["Légumes", "Crevettes", "Trois fromages fondants, crème de labneh persillée", "Viande hachée"]', 2, '« Thalata » veut dire trois en arabe : trois fromages.', true, 1, 'qcm', null, 'carte'),
('b27d9ce0-704b-4d72-9226-82089152a26b', 'zz', 'À partager', 'Le Houmouss Fatteh est une fusion…', '["Marocaine et française", "Turque et grecque", "Indienne", "Libanaise et syrienne, éclats croustillants de pita"]', 3, '100 DH, idéal à partager en début de repas.', true, 1, 'qcm', null, 'carte'),
('e5378204-6089-4f29-81b7-e6d98c1a6d35', 'zz', 'Plus ou moins', 'Lequel est le plus cher ?', '["Le NoorShems", "Le Snake Dance"]', 0, 'NoorShems 170 DH, Snake Dance 160 DH.', true, 1, 'price', null, 'carte'),
('040c63a5-9f8a-41eb-b279-c8772ff85ff8', 'zz', 'À partager', 'Le Ceviche Barba est préparé avec…', '["Thon rouge", "Loup bar mariné à la betterave, marinade berbère à la coriandre", "Saumon au citron", "Poulpe"]', 1, '150 DH, frais et acidulé.', true, 2, 'qcm', null, 'carte'),
('05d7c87c-ac51-4dfe-adc5-404f0fdac2b4', 'baro', 'Cuisine Baro', 'Le plat « Héritage Marocain » est…', '["Un couscous", "Une harira", "Un effiloché de poulet fermier, sauce ancestrale au citron confit", "Un tajine d''agneau"]', 2, 'Avec pommes de terre aux herbes. 240 DH.', true, 2, 'qcm', null, 'carte'),
('17ac8d2a-2df1-41b3-8d1c-78733c6ce0fe', 'baro', 'Cuisine Baro', 'Les Cromesquis de tanjia sont relevés avec…', '["De la truffe", "Du parmesan", "Du citron confit", "Du chocolat"]', 2, 'La tanjia, plat emblématique de Marrakech, en bouchée croustillante. 80 DH.', true, 2, 'qcm', null, 'carte'),
('267d611b-055a-4f33-ad6c-ebfd386a9057', 'zz', 'Terrasse', 'Quel mocktail de terrasse reprend la recette du Snake Dance sans alcool ?', '["Colada Blossom", "Detox", "L''Exotique Épicé", "Mojito"]', 2, 'Mangue, citron, gingembre et vanille pimentée, 80 DH.', true, 2, 'qcm', null, 'carte'),
('341b2d59-227e-4a3a-8087-2dfc3915956b', 'baro', 'Cuisine Baro', 'Quels deux plats de la carte « Sharing » sont signalés comme pimentés ?', '["Brie pané et burrata", "Mini burgers et olives", "Houmous et carpaccio", "Toast de bœuf chimichurri et Daurade façon ceviche à la mangue"]', 3, 'Toujours prévenir le client du piquant avant qu''il commande.', true, 2, 'qcm', null, 'carte'),
('3d8035b9-33c2-447a-a903-b8a492d3efd5', 'baro', 'Cuisine Baro', '« À travers le Maroc », c''est…', '["Un cocktail", "4 salades marocaines incontournables", "Un menu dégustation", "Un plateau de fromages"]', 1, '90 DH, parfait pour faire découvrir le Maroc à une table de touristes.', true, 2, 'qcm', null, 'carte'),
('5577dba3-588f-4641-a6a5-99f78fd042c1', 'zz', 'Terrasse', 'Le Colada Blossom en terrasse est la version sans alcool de…', '["Cardarita", "Scorpion", "Khamsa Colada", "Mojito Soltane"]', 2, 'Cordial d''ananas à la fleur d''oranger, orgeat et citron.', true, 2, 'qcm', null, 'carte'),
('5be2fe98-8818-4d41-b38a-841b52c4e84f', 'zz', 'À partager', 'Comment sont cuisinées les Gambas de Carthage ?', '["Grillées nature", "Crues en ceviche", "Poêlées à la harissa, beurre citronné et aillé", "Frites"]', 2, '160 DH, un plat relevé : proposer un cocktail frais à côté.', true, 2, 'qcm', null, 'carte'),
('6988505b-61aa-4c21-bd37-7350964934b7', 'zz', 'Plats Zama', 'Le Tigre qui Danse est un plat de…', '["Poulet grillé", "Agneau", "Poisson", "Filet de bœuf en lamelles sauce umami au ras el hanout et gingembre"]', 3, 'Servi avec gratin dauphinois à la noix de muscade. 290 DH.', true, 2, 'qcm', null, 'carte'),
('7e49fef5-f3b7-4b43-abda-079f8d64cfb3', 'zz', 'Plats Zama', 'L''Agneau Samarkand, ce sont des côtelettes avec…', '["Des frites", "Une purée", "Du riz au curry", "Un beurre noisette aux câpres et des gnocchis aux herbes"]', 3, 'Côtelettes d''agneau, beurre noisette de câpres, gnocchis aux herbes aromatiques.', true, 2, 'qcm', null, 'carte'),
