('963982bb-0f34-43eb-b893-dfba9c050aeb', null, 'Bar en images', 'Une bière pression se sert avec…', '["Aucune mousse", "Le verre droit dès le début", "Moitié mousse", "Un col de mousse d''environ deux doigts"]', 3, 'On penche le verre, puis on le redresse pour former un col de mousse.', true, 2, 'image', '{"img": "d1a269cf713d"}', 'cocktails'),
('9fa50a32-323e-452b-8cab-1c20d23461e9', null, 'Bar en images', 'Dans ce verre bas, on sert typiquement…', '["Une bière pression", "Un Old Fashioned", "Du champagne", "Un Spritz"]', 1, 'Le tumbler (old fashioned) accueille les cocktails courts sur glace.', true, 2, 'image', '{"img": "15404907ea64"}', 'cocktails'),
('a0fdbef4-69e1-46c9-a363-d9de26d3e4f3', null, 'Bar en images', 'Le Bee''s Knees, c''est gin, citron et…', '["Du miel", "Du sucre de canne", "Du sirop d''orgeat", "De la grenadine"]', 0, 'Un classique de la Prohibition : gin, citron, miel.', true, 2, 'image', '{"img": "b8c6432d1e53"}', 'cocktails'),
('a27aee0c-5511-48cc-8c44-cdd00e6348a6', null, 'Spiritueux', 'Le mezcal San Cosme de la carte vient de quel État mexicain réputé pour le mezcal ?', '["Jalisco", "Yucatán", "Sonora", "Oaxaca"]', 3, 'Oaxaca est la capitale du mezcal, souvent au goût fumé.', true, 2, 'qcm', null, 'cocktails'),
('acda5301-aebf-4c16-b8db-90006509049a', null, 'Bar en images', 'Ce duo verre et timbale en métal, c''est…', '["Un doseur", "Un shaker Boston", "Un verre à mélange", "Un shaker cobbler"]', 1, 'Le Boston = un verre + une timbale. Le cobbler a 3 pièces avec une passoire intégrée.', true, 2, 'image', '{"img": "4bf26dc95ce1"}', 'cocktails'),
('ae7993d2-48c6-4d55-8f2e-700da1d41d31', null, 'Associations', 'Relie chaque spiritueux à son pays', '[]', 0, 'Le tour du monde au comptoir.', true, 2, 'match', '{"pairs": [["Tequila", "Mexique"], ["Cognac", "France"], ["Scotch", "Écosse"], ["Zacapa", "Guatemala"]]}', 'cocktails'),
('b701190d-731e-4b5e-a1ee-b26aa8d68e8b', null, 'Vrai ou faux', 'On sait exactement qui a inventé la Margarita.', '["Vrai", "Faux"]', 1, 'Faux ! Plusieurs bars et bartenders revendiquent sa création. Le mystère fait partie de la légende.', true, 2, 'tf', null, 'cocktails'),
('b91dfe6d-90d2-4d76-b120-9cced35bacb8', 'zz', 'Cocktails Zama', 'Le Rose de Damas, c''est…', '["Vodka, dattes et prosecco", "Gin parfumé à la rose, sirop maison d''hibiscus et citron", "Rhum et géranium", "Tequila infusée à la cardamome"]', 1, 'Léger et floral : gin à la rose, hibiscus maison et citron.', true, 2, 'qcm', null, 'cocktails'),
('b94d2664-0bdd-42f0-ad5a-3f84106803b4', 'zz', 'Cocktails Zama', 'Quel ingrédient marocain est mis en macération dans le Scorpion ?', '["Fleur d''oranger", "Safran", "Harissa", "Amlou"]', 2, 'Scorpion : tequila, cordial de citron aux poivrons, macération à la harissa. « Intense et épicé ».', true, 2, 'qcm', null, 'cocktails'),
('bc795c92-1179-469b-8a0c-984cf98dd7aa', 'baro', 'Cocktails Baro', 'Pourquoi le cocktail Churchill porte ce nom ?', '["Pour son goût de cigare uniquement", "Il a été créé à Londres", "C''est sa recette personnelle", "Churchill était un fidèle visiteur de Marrakech"]', 3, 'Whisky infusé aux pruneaux, caroube, orange, safran, cannelle et bitter. « Deep & Woody », 175 DH.', true, 2, 'qcm', null, 'cocktails'),
('bf163f2a-07eb-4ba0-a4dd-a34615c77b81', null, 'Vrai ou faux', 'Un Scotch whisky doit vieillir au moins 3 ans en fût de chêne.', '["Vrai", "Faux"]', 0, 'Vrai ! C''est la règle minimum en Écosse.', true, 2, 'tf', null, 'cocktails'),
('c65ba04d-90ad-40d3-8e4d-77d96c9db8d2', 'zz', 'Cocktails Zama', 'Quel cocktail utilise un whisky infusé à l''orange avec ras el hanout et safran ?', '["Berberliner", "Marrakesh Market", "Old Fashioned", "Whisky Sour"]', 1, 'Marrakesh Market : « fumé et épicé », whisky infusé à l''orange, ras el hanout, safran, citron et bitter maison.', true, 2, 'qcm', null, 'cocktails'),
('c94fdc1b-0d88-4a34-bc29-a565fe95e713', 'baro', 'Cocktails Baro', 'Comment se servent nos shots de tequila signature ?', '["Flambés", "Avec citron et sel uniquement", "Avec sel, olives, pickles et concombre", "Avec du Red Bull"]', 2, '« À déguster comme il se doit » : un vrai rituel à présenter au client.', true, 2, 'qcm', null, 'cocktails'),
('d5656541-5967-4c16-983c-aed9f0709b86', null, 'Mixologie', 'À quoi servent les bitters (Angostura…) ?', '["À colorer seulement", "À assaisonner et lier les saveurs", "À remplacer l''alcool", "À sucrer"]', 1, 'Quelques traits suffisent : ce sont les épices du bartender.', true, 2, 'qcm', null, 'cocktails'),
('df8955bb-f59d-49d7-ace2-377c9da9e405', null, 'Vrai ou faux', 'L''Espresso Martini a été créé à Londres dans les années 1980.', '["Vrai", "Faux"]', 0, 'Vrai ! Par le bartender Dick Bradsell, pour une cliente qui voulait un verre pour la réveiller.', true, 2, 'tf', null, 'cocktails'),
('e40a4319-02e5-456b-b881-a058515b562f', null, 'Bar en images', 'Cet outil sert à…', '["Prélever de fins zestes d''agrume", "Ouvrir les huîtres", "Couper la viande", "Hacher les herbes"]', 0, 'Le zesteur prend la peau parfumée sans la partie blanche amère.', true, 2, 'image', '{"img": "47555a620378"}', 'cocktails'),
('e6f0e69f-ab24-4b31-a03b-ddbf75635f0c', 'zz', 'Cocktails Zama', 'Le Dolce Hayat contient un sorbet de…', '["Grenade", "Figue", "Mangue", "Dattes Majhoul"]', 3, 'Vodka sur sorbet de dattes Majhoul, fleur de sureau et prosecco.', true, 2, 'qcm', null, 'cocktails'),
('ea4c439b-dbbf-4b14-ba47-222c440ae3ad', 'baro', 'Cocktails Baro', 'Le Mooja se savoure « dans le creux de la vague ». Ses saveurs ?', '["Gin et rose", "Whisky et truffe", "Rhum au citron vert, ananas, orgeat, coco, fleur d''oranger", "Tequila et harissa"]', 2, '« Fruity & Floral », 160 DH, existe aussi sans alcool.', true, 2, 'qcm', null, 'cocktails'),
('eb87f2af-4b9c-402a-bce8-f2a5cc58fb46', null, 'Vrai ou faux', 'Un bourbon doit obligatoirement être fabriqué au Kentucky.', '["Vrai", "Faux"]', 1, 'Faux ! Il doit être fait aux États-Unis. Le Kentucky en produit la grande majorité, mais pas l''exclusivité.', true, 2, 'tf', null, 'cocktails'),
('ebf514cd-fb0f-4cbd-919a-15cb1272149e', 'baro', 'Cocktails Baro', 'Le Botanic Gin Tonic est allongé avec…', '["Eau gazeuse", "Prosecco", "Swiss Mountain Tonic", "Schweppes"]', 2, 'Gin au citron vert et curcuma, gingembre, cardamome, coriandre, romarin et poivre noir.', true, 2, 'qcm', null, 'cocktails'),
('f94ef683-d7cc-447f-b937-6849db98aeca', null, 'Vrai ou faux', 'Les bartenders recommandent de secouer un Dry Martini, comme James Bond.', '["Vrai", "Faux"]', 1, 'Faux ! Un cocktail sans jus se remue : il reste limpide et soyeux. Bond, lui, le voulait secoué.', true, 2, 'tf', null, 'cocktails'),
('f9cb21db-819a-4d0a-bebb-e904e33ad4a5', null, 'Vrai ou faux', 'Le ver dans la bouteille fait partie de la tradition de tous les mezcals.', '["Vrai", "Faux"]', 1, 'Faux ! C''était surtout un coup marketing. Les grands mezcals n''en ont pas.', true, 2, 'tf', null, 'cocktails'),
('fe486e27-bb31-455f-8f22-cdc0075f65ba', null, 'Spiritueux', 'Pourquoi le mezcal a-t-il souvent un goût fumé ?', '["On y ajoute de la fumée liquide", "Le cœur d''agave est cuit dans des fours en terre", "Il vieillit dans des fûts brûlés", "À cause du ver"]', 1, 'Les cœurs d''agave (piñas) sont cuits lentement dans des fosses chauffées au bois.', true, 2, 'qcm', null, 'cocktails'),
('1477a652-2761-45e5-9a5f-2df9449c0c6f', 'zz', 'Cocktails Zama', 'Le Berberliner utilise un whisky « fat-washed » à…', '["Le beurre", "L''huile d''argan", "L''huile de sésame", "L''huile d''olive"]', 1, 'Fat-wash à l''huile d''argan, amlou, miel d''amande et bitter. « Bold & strong ».', true, 3, 'qcm', null, 'cocktails'),
('14f176c0-6e63-4cd3-aefb-95d52ea284b2', 'zz', 'Cocktails Zama', 'La tequila du Cardarita est infusée à…', '["La cannelle", "La vanille", "La cardamome", "Le safran"]', 2, 'Tequila à la cardamome et cordial de céleri au citron. 170 DH.', true, 3, 'qcm', null, 'cocktails'),
('16827270-9211-4b36-8d52-5e2fafd1a08c', null, 'Vrai ou faux', 'Le Penicillin est un cocktail créé au XIXe siècle par un médecin.', '["Vrai", "Faux"]', 1, 'Faux ! Il a été créé en 2005 à New York par le bartender Sam Ross, au bar Milk & Honey.', true, 3, 'tf', null, 'cocktails'),
('22f22e0a-00bf-4dad-aac8-2630be49a653', null, 'Vrai ou faux', 'Le Cognac est une eau-de-vie de raisin.', '["Vrai", "Faux"]', 0, 'Vrai ! Distillé deux fois puis vieilli en fût de chêne, dans la région de Cognac.', true, 3, 'tf', null, 'cocktails'),
('41b973e3-438d-4c50-90f7-b63d0adf3bfd', 'baro', 'Cocktails Baro', 'Quelle différence entre le Marrakesh Market du Baromètre et celui de ZamaZama ?', '["Aucune", "Celui de Zama est sans alcool", "La version Zama ajoute du safran", "Celui du Baro est à la tequila"]', 2, 'Base commune : whisky infusé à l''orange, ras el hanout, citron et bitter maison.', true, 3, 'qcm', null, 'cocktails'),
('490e71e8-293d-41c6-a4b5-58e6951b6f09', 'baro', 'Cocktails Baro', 'Le Lust Martini est décrit comme…', '["Amer et sec", "Fumé et boisé", "Salé et umami", "Fruité et aphrodisiaque : vodka, mangue, passion, vanille et muscade"]', 3, '« Élégant, mais joueur ». Fait partie des choix de l''Eye Contact.', true, 3, 'qcm', null, 'cocktails'),
('99036074-d519-44b0-b849-f739440dfe38', 'baro', 'Cocktails Baro', 'Quel cocktail Baromètre est un Mojito revisité avec rhum à la citronnelle, cordial clarifié et espuma ?', '["Le Mojito Soltane", "Le Mojito Especial", "Le Mooja", "L''Antidote"]', 1, '130 DH. À ne pas confondre avec le Mojito Soltane de ZamaZama.', true, 3, 'qcm', null, 'cocktails'),
('9b923184-760d-4f89-a2aa-0534ab9df759', 'zz', 'Cocktails Zama', 'Lequel de ces signatures n''existe PAS en virgin ?', '["Rose de Damas", "Scorpion", "Berberliner", "Snake Dance"]', 2, 'NoorShems, Dolce Hayat et Berberliner n''ont pas de version virgin.', true, 3, 'qcm', null, 'cocktails'),
('b5df6633-b2ff-4503-bd98-e304fe3bd87a', null, 'Vrai ou faux', 'À l''origine, la couleur rouge du Campari venait d''un insecte, la cochenille.', '["Vrai", "Faux"]', 0, 'Vrai ! Le colorant carmin a été remplacé depuis par un colorant artificiel.', true, 3, 'tf', null, 'cocktails'),
('c3adf957-8af8-4d6c-86ba-dafe816af476', null, 'Vrai ou faux', 'La Piña Colada est la boisson nationale de Porto Rico.', '["Vrai", "Faux"]', 0, 'Vrai ! Officiellement depuis 1978.', true, 3, 'tf', null, 'cocktails'),
('cb8b323f-0577-4a08-8bc8-94d971a83115', 'zz', 'Cocktails Zama', 'Le Tomatini est surmonté d''une mousse légère de…', '["Blanc d''œuf", "Yaourt", "Fromage frais", "Coco"]', 2, 'Gin, eau de tomate à l''origan clarifiée et carbonatée, mousse de fromage frais.', true, 3, 'qcm', null, 'cocktails'),
('d9a29db8-b143-4b4a-8bea-903892a3a999', 'baro', 'Cocktails Baro', 'Quelle est la différence entre nos shots Snake Bite et Antidote ?', '["Antidote est au whisky", "Ce sont les mêmes", "Snake Bite : tequila, Red Bull réduit, gingembre, piment ; Antidote : gin, ananas, rose, citron", "Snake Bite est sans alcool"]', 2, '80 DH chacun : le poison et son remède, à proposer en duo.', true, 3, 'qcm', null, 'cocktails'),
('e09b96a3-969e-4744-aab6-75f7ada2aa68', 'baro', 'Cocktails Baro', 'Le Crystal Meth associe tequila, citron et gingembre avec…', '["Truffe et miel", "Rose et camomille", "Curaçao bleu et cardamome", "Pruneau et caroube"]', 2, '« Bright & Bold » : une alchimie intense, au visuel bleu.', true, 3, 'qcm', null, 'cocktails'),
('e55db082-2b87-4164-9c66-6c12d6954ed8', null, '50 Best', 'Ce qui fait un bar de niveau 50 Best, c''est d''abord…', '["Une longue carte", "Un décor cher", "Des prix bas", "L''hospitalité et l''expérience client autant que les cocktails"]', 3, 'Les meilleurs bars du monde sont d''abord des maisons d''accueil : on se souvient de comment on a été reçu.', true, 3, 'qcm', null, 'cocktails'),
('f9ce157c-f01b-4db9-9d10-e75741db4c25', null, 'Mixologie', 'La « dilution » dans un cocktail, c''est…', '["Un sirop", "Un type de verre", "L''eau apportée par la glace, essentielle à l''équilibre", "Une erreur"]', 2, 'La glace qui fond fait partie de la recette : sans dilution, le cocktail est trop fort et déséquilibré.', true, 3, 'qcm', null, 'cocktails'),
('fe0984c7-0212-441c-a669-67cfa695681d', null, 'Spiritueux', 'Le Zacapa 23 de la carte est un rhum de quel pays ?', '["Guatemala", "Jamaïque", "Martinique", "Cuba"]', 0, 'Un rhum vieilli en altitude, réputé pour sa rondeur.', true, 3, 'qcm', null, 'cocktails'),
('028333ad-e4be-4ef0-a67c-638150f756df', null, 'Cuisine en images', 'À quoi sert la balance en cuisine ?', '["Décorer", "Respecter les grammages des fiches techniques", "Peser les clients", "À rien"]', 1, 'Même grammage = même goût, même coût, même assiette.', true, 1, 'image', '{"img": "a5a6d5511bdd"}', 'cuisine'),
('105783c8-7966-432e-8bc2-1bc5f8962b2f', null, 'Cuisine en images', 'Comment s''appelle cet ustensile ?', '["Une pince", "Une écumoire", "Un fouet", "Un chinois"]', 2, 'Le fouet incorpore de l''air : crème montée, blancs, sauces.', true, 1, 'image', '{"img": "5e64093191b2"}', 'cuisine'),
('215c6ceb-6b95-48ce-a195-c9f94006c5e4', null, 'Cuisine en images', 'Température d''un frigo de produits frais ?', '["0 à 4 °C", "−18 °C", "12 °C", "8 à 10 °C"]', 0, '0 à 4 °C pour les produits frais. −18 °C, c''est le congélateur.', true, 1, 'image', '{"img": "ce1c63ed8cf5"}', 'cuisine'),
('21ba0385-d3fd-4f20-aaf3-0f814e5427b8', null, 'Cuisine', 'Comment décongèle-t-on un produit ?', '["Sur le plan de travail", "Dans l''eau chaude", "Au soleil", "Au réfrigérateur"]', 3, 'Lentement au froid : jamais à température ambiante.', true, 1, 'qcm', null, 'cuisine'),
('6638d7a5-8757-4caf-9066-18ff20218984', null, 'Cuisine en images', 'Comment s''appelle cet ustensile ?', '["Une louche", "Une écumoire", "Une cuillère à soupe", "Un chinois"]', 0, 'La louche sert à servir et doser les liquides : soupes, sauces.', true, 1, 'image', '{"img": "d61da9544421"}', 'cuisine'),
('70edc250-208e-40fe-848b-d97d2de2af08', null, 'Cuisine', 'La planche à découper rouge est réservée…', '["Au poisson", "Au pain", "Aux légumes", "À la viande crue"]', 3, 'Code couleur courant : rouge viande crue, bleu poisson, vert légumes, jaune volaille, blanc pain et laitages.', true, 1, 'qcm', null, 'cuisine'),
('78fb80dc-ce33-497d-bf75-4bed165e5c70', null, 'Cuisine', 'À quelle température garde-t-on les produits frais au réfrigérateur ?', '["Entre 0 et 4 °C", "Entre 8 et 12 °C", "À −18 °C", "Autour de 15 °C"]', 0, '0 à 4 °C pour les produits très périssables. Au-dessus, les bactéries se multiplient vite.', true, 1, 'qcm', null, 'cuisine'),
('8c0443ed-d60f-4616-bc49-c4a6605ead04', null, 'Cuisine', 'Un plat chaud en attente de service doit rester à…', '["Température ambiante", "25 °C", "40 °C", "63 °C minimum"]', 3, 'En dessous de 63 °C, on entre dans la zone où les bactéries se développent.', true, 1, 'qcm', null, 'cuisine'),
('bee855ab-8e6f-4d14-af6e-7dc498e3916e', null, 'Cuisine en images', 'Une préparation maison sans étiquette au frigo…', '["Est donnée au personnel", "Va au congélateur", "Doit être jetée", "Peut servir si elle sent bon"]', 2, 'Pas d''étiquette = pas de date = on jette.', true, 1, 'image', '{"img": "d8784714dbb0"}', 'cuisine'),
('c079967d-3251-4d4c-8f8a-c7bc374f028b', null, 'Cuisine', 'On peut recongeler un produit qui a été décongelé.', '["Vrai", "Faux"]', 1, 'Faux ! Un produit décongelé ne se recongèle jamais tel quel. On le cuisine, ou on le jette.', true, 1, 'tf', null, 'cuisine'),
('d09df3b0-af48-46d5-90fa-49e90b5741ba', null, 'Associations', 'Relie chaque planche à son usage', '[]', 0, 'Le code couleur évite les contaminations.', true, 1, 'match', '{"pairs": [["Rouge", "Viande crue"], ["Bleue", "Poisson"], ["Verte", "Légumes"], ["Jaune", "Volaille"]]}', 'cuisine'),
('ddcffb8b-8a56-4a64-a12b-5d5828b3e4d0', null, 'Cuisine en images', 'Comment s''appelle cet ustensile ?', '["Une écumoire", "Un fouet", "Une louche", "Une spatule"]', 3, 'La spatule coudée sert à retourner, lisser et dresser.', true, 1, 'image', '{"img": "8340633360a1"}', 'cuisine'),
('ed81136e-45cc-461c-a30f-4baf83f4b738', null, 'Cuisine', 'La température d''un congélateur doit être de…', '["0 °C", "−5 °C", "−18 °C ou moins", "−2 °C"]', 2, '−18 °C bloque le développement des bactéries.', true, 1, 'qcm', null, 'cuisine'),
('f48d406a-fb0d-4322-9c04-5e9ce1c37825', null, 'Cuisine en images', 'Tu te coupes en cuisine. Premier réflexe ?', '["Continuer et soigner plus tard", "Mettre le doigt dans la glace", "Arrêter, laver, désinfecter, pansement et gant", "Rien, c''est petit"]', 2, 'Un pansement bleu et un gant : pour toi et pour l''assiette.', true, 1, 'image', '{"img": "ce81ff78adb6"}', 'cuisine'),
('08d102ad-8a53-4294-90d6-7c205caa6ab1', null, 'Cuisine', 'Combien d''allergènes majeurs doivent être signalés selon la réglementation européenne ?', '["5", "14", "30", "8"]', 1, 'Gluten, crustacés, œufs, poissons, arachides, soja, lait, fruits à coque, céleri, moutarde, sésame, sulfites, lupin, mollusques.', true, 2, 'qcm', null, 'cuisine'),
('32a4d5ca-c415-471b-8577-9ea568116478', null, 'Cuisine', 'Une friteuse prend feu. Le bon réflexe ?', '["Jeter de l''eau", "Déplacer la friteuse", "Couper le feu et étouffer avec un couvercle ou une couverture anti-feu", "Souffler dessus"]', 2, 'Jamais d''eau sur de l''huile en feu : elle provoque une explosion de flammes.', true, 2, 'qcm', null, 'cuisine'),
('64f917ca-6550-4733-9273-8a8556f7ef20', null, 'Cuisine', 'La « contamination croisée », c''est…', '["Une erreur de commande", "Le transfert de bactéries ou d''allergènes d''un aliment à un autre", "Un mélange de deux sauces", "Un plat trop cuit"]', 1, 'Exemple : couper du poulet cru puis une salade avec le même couteau.', true, 2, 'qcm', null, 'cuisine'),
('7e29b11e-da65-4224-bf13-ba1c82e310fd', null, 'Cuisine', 'Dans une brigade, qui seconde directement le chef ?', '["Le plongeur", "Le sous-chef", "Le chef de rang", "Le commis"]', 1, 'Le sous-chef (ou second) remplace le chef en son absence.', true, 2, 'qcm', null, 'cuisine'),
('9d754405-6f19-455b-ab48-48560467b4de', null, 'Cuisine en images', 'Ce crustacé à grosses pinces, c''est…', '["Une langouste", "Un homard", "Une écrevisse", "Un crabe"]', 1, 'Le homard a deux grosses pinces. La langouste n''en a pas.', true, 2, 'image', '{"img": "c55bda3a01cd"}', 'cuisine'),
('b1debc4c-f848-4420-b20e-5359c4b693ce', null, 'Cuisine', 'Les montres et bracelets sont interdits en cuisine.', '["Vrai", "Faux"]', 0, 'Vrai ! Ils retiennent les bactéries et peuvent tomber dans les plats.', true, 2, 'tf', null, 'cuisine'),
('b2662b1b-1960-49e2-98f6-03dbb1346c0d', null, 'Cuisine', 'Un client allergique aux fruits à coque commande. Que fais-tu en cuisine ?', '["Vérifier la recette, utiliser des ustensiles propres et prévenir le chef", "Ajouter un peu moins de fruits à coque", "Enlever les noix visibles", "Rien, c''est au serveur de gérer"]', 0, 'Une trace suffit à déclencher une réaction grave.', true, 2, 'qcm', null, 'cuisine'),
('da454f09-e798-4aff-b10e-5897e9bda9e3', null, 'Cuisine en images', 'Cette passoire conique s''appelle…', '["Un entonnoir", "Un chinois", "Un tamis plat", "Une passoire à thé"]', 1, 'Le chinois filtre les sauces et les fonds pour une texture lisse.', true, 2, 'image', '{"img": "583a4f58e508"}', 'cuisine'),
('dea9714c-a7cd-4599-88f3-52a507095dbd', null, 'Cuisine', 'Une préparation maison mise au frigo doit porter…', '["Son nom, sa date de fabrication et sa date limite", "Le prénom du cuisinier uniquement", "Seulement le prix", "Rien si c''est pour le jour même"]', 0, 'Sans étiquette, un produit maison doit être jeté.', true, 2, 'qcm', null, 'cuisine'),
('fa6d2569-442d-4a9f-b7ab-3335b6a5e754', null, 'Cuisine en images', 'Une éponge sale en cuisine, c''est…', '["Pratique pour les planches à viande", "Un nid à bactéries : on la change souvent", "Mieux qu''un torchon propre", "Sans danger si elle est rincée"]', 1, 'L''éponge humide est l''un des objets les plus contaminés d''une cuisine.', true, 2, 'image', '{"img": "ff1b0ad4092f"}', 'cuisine'),
('06d9e3f7-2913-4e4e-969a-71cea34d13a1', null, 'Cuisine en images', 'Monter une sauce au beurre, c''est…', '["Ajouter du beurre froid hors du feu en fouettant", "Faire noircir le beurre", "Ajouter de la farine", "Faire bouillir fort"]', 0, 'Le beurre froid émulsionne la sauce et la rend brillante.', true, 3, 'image', '{"img": "76bf780cfc07"}', 'cuisine'),
('1000bbbd-4e09-4784-a33c-86a6b5a85625', null, 'Cuisine', 'Que veut dire HACCP ?', '["Hygiène, alimentation, cuisine, contrôle, propreté", "Haute cuisine et contrôle des produits", "Analyse des dangers et points critiques pour leur maîtrise", "Une marque de détergent"]', 2, 'La méthode qui organise la sécurité alimentaire en cuisine.', true, 3, 'qcm', null, 'cuisine'),
('1528f1fb-55b7-458c-b6d4-c1cda5ab8f3e', null, 'Cuisine', 'Un refroidissement rapide doit faire passer un plat de 63 °C à moins de 10 °C en…', '["6 heures", "30 minutes exactement", "Une nuit", "Moins de 2 heures"]', 3, 'C''est le rôle de la cellule de refroidissement.', true, 3, 'qcm', null, 'cuisine'),
('3b842f0b-1d6d-4ebc-864f-ac590ac73a9c', null, 'Cuisine', 'Quelle différence entre DLC et DDM ?', '["DLC : date stricte à ne pas dépasser ; DDM : date de qualité optimale", "Aucune", "DLC concerne seulement les boissons", "DDM est plus stricte"]', 0, 'Après la DLC, on jette. Après la DDM, le produit peut perdre en goût sans être dangereux.', true, 3, 'qcm', null, 'cuisine'),
('a415f255-7011-485d-9a80-55afb0d5b11a', null, 'Cuisine', 'Lequel fait partie des 14 allergènes majeurs ?', '["Le poulet", "Le riz", "Le sésame", "La tomate"]', 2, 'Le sésame est très présent dans les cuisines orientales : attention au tahiné.', true, 3, 'qcm', null, 'cuisine'),
('b1519451-c45f-4b08-b742-6024cf582e1d', null, 'Cuisine', 'Une « brunoise », c''est…', '["Une cuisson au four", "Un dessert", "Une sauce brune", "Une taille en tout petits dés"]', 3, 'Julienne = fins bâtonnets, brunoise = petits dés réguliers.', true, 3, 'qcm', null, 'cuisine'),
('d54e0bb1-d42e-47c9-a5d7-08acf5ae0207', null, 'Cuisine en images', 'Une viande « saignante » a une température à cœur d''environ…', '["30 °C", "70 °C", "50 à 55 °C", "85 °C"]', 2, 'Bleu ≈ 45 °C, saignant ≈ 52 °C, à point ≈ 60 °C, bien cuit ≈ 70 °C.', true, 3, 'image', '{"img": "d53e5b690bb8"}', 'cuisine'),
('f95d22b5-9fb4-4dc2-aceb-fb2749c52ae7', null, 'Cuisine en images', 'Pour un poisson, une cuisson parfaite se dit…', '["Nacrée", "Rosée", "Bien cuite", "Bleue"]', 0, 'Nacrée : la chair se détache en lamelles brillantes et reste moelleuse.', true, 3, 'image', '{"img": "d806af440c34"}', 'cuisine'),
('1b19a89a-2f02-4d84-b8b0-619bf027d4e7', 'zz', 'Storytelling', 'Comment Zama définit sa cuisine ?', '["Gastronomie italienne", "Cuisine française classique", "Arabesque Fusion", "Street food"]', 2, 'Arabesque Fusion : Cuisine, Mixology, Celebration.', true, 1, 'qcm', null, 'histoire'),
('44746f95-3ebe-41d5-ad9c-34d87ea8e0ae', 'zz', 'Histoire Zama', 'Quand ZamaZama a-t-il ouvert ?', '["Janvier 2020", "Décembre 2016", "Septembre 2025", "Avril 2026"]', 3, 'Ouverture le 23 avril 2026.', true, 1, 'qcm', null, 'histoire'),
('47262a14-5933-4ace-b3c0-650ebc634eb8', 'baro', 'Histoire Baro', 'Pourquoi il n''y a pas d''enseigne lumineuse à l''entrée du Baromètre ?', '["La mairie l''interdit", "Pour économiser", "Par oubli", "C''est voulu, esprit speakeasy : on vient parce qu''on sait"]', 3, 'Une porte discrète au pied d''un petit escalier : la découverte fait partie de l''expérience.', true, 1, 'qcm', null, 'histoire'),
('527d25fc-a8d1-45c7-9093-4072574e1b69', 'baro', 'Histoire Baro', 'En quelle année a ouvert le Baromètre ?', '["2022", "2016", "2019", "2010"]', 1, '2016 : l''Apothicaire est notre signature depuis le premier jour.', true, 1, 'qcm', null, 'histoire'),
('79ef99e2-317c-479d-9271-a790a0e1ec32', 'baro', 'Histoire Baro', 'Comment s''appelle la « sœur orientale » du Baromètre ?', '["Epicure", "ZamaZama", "Azyr", "CarpeDiem"]', 1, 'Zama Zama, à la M Avenue : la carte cocktails a été pensée avec l''équipe du Baromètre.', true, 1, 'qcm', null, 'histoire'),
('7a39371d-77e9-464f-868d-b031a790f53d', 'baro', 'Histoire Baro', 'Selon le New York Times, qui a ouvert le Baromètre en 2016 ?', '["Un groupe hôtelier", "Un bartender londonien", "Un chef français", "Les frères Hamza et Soufiane Hadni"]', 3, 'D''après le NYT (2018), deux frères marrakchis sans expérience du bar à l''époque.', true, 1, 'qcm', null, 'histoire'),
('8bda6e0a-8cb6-4d24-a936-b491d3b42e1f', 'zz', 'Storytelling', 'Quel animal est l''emblème de Zama Zama ?', '["Le lion", "L''aigle", "Le serpent", "Le dromadaire"]', 2, 'Le serpent « ne dort jamais, il veille sur ce qui est précieux ». Zama est née sous son signe.', true, 1, 'qcm', null, 'histoire'),
('c3d9338c-b80e-4937-9600-b84626acc991', 'zz', 'Histoire Zama', 'Où se trouve ZamaZama ?', '["À Guéliz, rue Moulay Ali", "À la Palmeraie", "À la M Avenue, Hivernage", "En médina"]', 2, 'Au cœur de la M Avenue, dans le quartier de l''Hivernage.', true, 1, 'qcm', null, 'histoire'),
('1f5d3078-952a-4a78-a898-d97f5bb20d67', 'zz', 'Histoire Zama', 'Combien de places compte ZamaZama ?', '["20 au bar", "40 en tout", "300 en salle", "110 en salle et 55 en terrasse"]', 3, 'Et le lieu peut être entièrement privatisé : pense à le proposer pour les événements.', true, 2, 'qcm', null, 'histoire'),
('ac29d015-3d63-4be6-baaf-bda03f7dc6e1', 'zz', 'Storytelling', 'Selon la carte, la générosité chez Zama est…', '["Un supplément", "Une option", "Réservée aux habitués", "Une philosophie"]', 3, '« La générosité est ici une philosophie » : à transmettre dans chaque service.', true, 2, 'qcm', null, 'histoire'),
('e2d5478f-bfcf-4b54-b021-022efcde858f', 'zz', 'Histoire Zama', 'Qui a conçu la carte cocktails de ZamaZama ?', '["Personne, ce sont des classiques", "Un fournisseur d''alcool", "Un consultant étranger", "L''équipe du Baromètre, en hommage à la culture arabe"]', 3, 'Zama est la sœur orientale du Baromètre.', true, 2, 'qcm', null, 'histoire'),
('56248e32-f5c6-4218-bb4f-87d6ede5c1d4', 'baro', 'Histoire Baro', 'Dans quel guide de The World''s 50 Best figure le Baromètre ?', '["Lonely Planet", "Michelin", "50 Best Discovery", "Gault et Millau"]', 2, 'Le guide 50 Best Discovery présente le Baromètre comme le premier bar de mixologie du Maroc.', true, 3, 'qcm', null, 'histoire'),
('69c23936-2c17-4d8e-a987-d131110895a7', 'zz', 'Storytelling', 'D''où vient le safran cité dans l''histoire de Zama ?', '["Essaouira", "Fès", "Taliouine", "Ouarzazate"]', 2, 'Le safran de Taliouine rencontre la mélasse de grenade : c''est l''esprit de la fusion Zama.', true, 3, 'qcm', null, 'histoire'),
('85cb5a5c-df37-48d2-826b-18e5978ae9b3', 'zz', 'Storytelling', 'Que symbolise l''œuf d''autruche dans l''histoire de Zama ?', '["La richesse", "La force", "La chance au jeu", "La renaissance et la possibilité"]', 3, 'Comme dans les sanctuaires soufis : une cuisine qui honore la mémoire pour mieux l''affranchir.', true, 3, 'qcm', null, 'histoire'),
('9e0bbd62-5b9e-44e6-96ee-7e213b5822f9', 'baro', 'Histoire Baro', 'Selon le guide 50 Best Discovery, le décor du Baromètre s''inspire de…', '["L''Asie", "Un laboratoire moderne en inox", "Souks, riads et hammams, avec cuivre et bocaux d''épices", "New York des années 80"]', 2, 'Notre univers apothicaire et laboratoire : instruments de mesure, fioles, bois sombre et laiton.', true, 3, 'qcm', null, 'histoire'),
('a1d81e06-7c47-45e2-acd7-f6a2f75fb4bf', 'zz', 'Histoire Zama', 'Quel collectif féminin de musique électronique marocaine est en résidence à Zama ?', '["Daft Punk", "Hoba Hoba Spirit", "Sound Sisters Morocco", "Gnawa Diffusion"]', 2, 'Deep house arabe et classiques régionaux revisités : l''âme festive de Zama.', true, 3, 'qcm', null, 'histoire'),
('b3b455c3-cac3-4c21-942b-466f9ad52c03', 'baro', 'Histoire Baro', 'Quel grand journal américain a parlé du Baromètre en 2018 ?', '["The Washington Post", "USA Today", "The Wall Street Journal", "The New York Times"]', 3, 'Le journaliste y décrivait le premier speakeasy de cocktails artisanaux du Maroc, et a goûté le Churchill.', true, 3, 'qcm', null, 'histoire'),
('24a3df61-a10a-4955-9ab3-648bc8d9e408', null, 'Service en images', 'Une table s''installe. En combien de temps l''accueille-t-on ?', '["5 minutes", "Après la commande", "Moins de 30 secondes", "Quand on a le temps"]', 2, 'Un regard et un mot dans les 30 secondes : le client se sent attendu.', true, 1, 'image', '{"img": "3b0e4b58dade"}', 'hospitalite'),
('2628c7a4-16d1-47ad-b6ba-1a022dbce18e', null, 'Hospitalité', 'Quand débarrasse-t-on les assiettes d''une table ?', '["Dès qu''une personne a fini", "Quand tout le monde a terminé", "À la fin du repas seulement", "Quand le client le demande"]', 1, 'Débarrasser trop tôt presse les convives qui mangent encore.', true, 1, 'qcm', null, 'hospitalite'),
('35c6dae8-4535-42b2-bf07-48cc193661ac', null, 'Service en images', 'Pourquoi sert-on la glace avec cette pince ?', '["C''est juste décoratif", "Pour que la glace ne fonde pas", "Par hygiène : jamais de glace à main nue", "Pour aller plus vite"]', 2, 'Toucher la glace à main nue est une ligne grise dans notre charte.', true, 1, 'image', '{"img": "88ccebdbd3d5"}', 'hospitalite'),
('37b370bb-67bd-4031-8c5c-78d6d16d7604', null, 'Règlement', 'Tu vas être en retard pour ton service. Tu dois…', '["Ne pas venir", "Prévenir un collègue après", "Prévenir ton responsable avant le début du service", "Arriver sans rien dire"]', 2, 'Prévenir avant, toujours. Ça permet de réorganiser le service.', true, 1, 'qcm', null, 'hospitalite'),
('56020324-5efe-4768-8d83-b361b2d81dbe', null, 'Hospitalité', 'Quelle est la différence entre le service et l''hospitalité ?', '["Le service est pour le bar, l''hospitalité pour la salle", "C''est la même chose", "L''hospitalité, c''est servir vite", "Le service, c''est ce que tu fais ; l''hospitalité, c''est ce que le client ressent"]', 3, 'Idée centrale du restaurateur Danny Meyer : on peut servir parfaitement sans faire sentir le client bienvenu.', true, 1, 'qcm', null, 'hospitalite'),
('62b19ade-98ac-4457-b891-21edbc633b0a', null, 'Hygiène', 'Quand faut-il se laver les mains ?', '["Jamais avec des gants", "Seulement en arrivant", "Une fois par heure", "À chaque changement de tâche, après la pause et après avoir touché argent ou déchets"]', 3, 'Mains propres à chaque changement de tâche : règle de base en restauration.', true, 1, 'qcm', null, 'hospitalite'),
('79bf616a-41df-471e-9777-670d7a75dcc6', null, 'Hospitalité', 'Comment présenter l''addition ?', '["En la lisant à voix haute", "Fermée, posée discrètement, sans rester au-dessus du client", "En attendant debout que le client paie", "Ouverte avec le total visible pour tous"]', 1, 'Discrétion : le client paie à son rythme, sans pression.', true, 1, 'qcm', null, 'hospitalite'),
('82a5cf87-59c8-441d-bd1a-39a5b53931cc', null, 'Service', 'Un client entre. Tu dois le saluer…', '["Seulement s''il s''approche du bar", "Quand il est assis", "Dans les premières secondes, même d''un regard", "Quand tu as fini ta tâche"]', 2, 'Un contact visuel et un sourire tout de suite : le client se sent attendu.', true, 1, 'qcm', null, 'hospitalite'),
('9b80afac-cc96-4b46-9897-9cb9db6dae7e', null, 'Hospitalité', 'Le verre d''eau d''un client est vide. Tu…', '["Lui proposes une autre bouteille payante tout de suite", "Ne fais rien", "Le remplis sans attendre qu''il le demande", "Attends qu''il t''appelle"]', 2, 'Anticiper le besoin avant qu''il soit exprimé : la base de l''hospitalité.', true, 1, 'qcm', null, 'hospitalite'),
('a9fb52b4-8089-4155-81b7-33fbb4e2f491', null, 'Hospitalité', 'Un client signale une allergie. Tu…', '["Lui dis que ça devrait aller", "Retires l''ingrédient visible", "Préviens la cuisine et vérifies la composition, sans jamais deviner", "Ne dis rien pour ne pas déranger"]', 2, 'Une allergie peut être grave. On vérifie toujours, on ne suppose jamais.', true, 1, 'qcm', null, 'hospitalite'),
('ae348f6d-0ec3-4187-9e56-857c350e249c', null, 'Service', 'Un client se plaint de son cocktail. Première réaction ?', '["Expliquer qu''il est fait selon la recette", "Appeler le manager sans rien dire", "Écouter, s''excuser et proposer de le refaire ou de le changer", "Ignorer"]', 2, 'On ne discute pas le goût d''un client. On écoute et on règle vite.', true, 1, 'qcm', null, 'hospitalite'),
('b1b2eb7f-a86c-409d-8f65-e73d14465300', null, 'Service', 'Retenir le prénom d''un habitué sert à…', '["Rien", "Le surveiller", "Faire plus vite l''addition", "Créer de la fidélité et une relation"]', 3, 'Un client reconnu revient. C''est la base de l''hospitalité.', true, 1, 'qcm', null, 'hospitalite'),
('c8acac2a-bf4f-4c0b-90df-9124f001998c', null, 'Service en images', 'Au passe, quand cette sonnette retentit…', '["Un client part", "Il faut changer la musique", "C''est la pause", "Un plat est prêt : on l''envoie tout de suite"]', 3, 'Un plat qui attend refroidit. On l''envoie dans la minute.', true, 1, 'image', '{"img": "a084db9be817"}', 'hospitalite'),
('dffee4a6-5e5d-4d07-8fc8-0921587ce601', null, 'Service en images', 'Combien de temps se laver les mains ?', '["Juste rincer à l''eau", "Au moins 30 secondes", "3 secondes", "Seulement en arrivant"]', 1, '30 secondes au savon, entre les doigts et sous les ongles.', true, 1, 'image', '{"img": "7572e4c6eaa6"}', 'hospitalite'),
('e42eadb3-b4d4-4757-b3a6-27f039657016', null, 'Service', 'Pour tenir un verre à pied correctement, on le prend…', '["À pleine main", "Par le pied ou la tige", "Par le bord", "Par le haut du verre"]', 1, 'Jamais de doigts sur le haut du verre : hygiène et température.', true, 1, 'qcm', null, 'hospitalite'),
('eb5e5aed-15a0-4f44-9c27-2e0b0117cb56', null, 'Valeurs', 'Un collègue est débordé en plein rush. Tu…', '["Te plains", "Attends que le manager le dise", "Continues ton poste uniquement", "Proposes ton aide dès que ton poste le permet"]', 3, 'Une équipe gagne ensemble : le client voit la salle entière, pas ton poste.', true, 1, 'qcm', null, 'hospitalite'),
('ecae244a-79e5-4d49-8cd2-3bc4bcff5890', null, 'Règlement', 'Le téléphone personnel pendant le service…', '["Autorisé derrière le bar", "Libre usage", "Rangé, sauf urgence et accord du responsable", "Autorisé si pas de client"]', 2, 'Le client doit sentir toute ton attention. Le téléphone reste rangé.', true, 1, 'qcm', null, 'hospitalite'),
('f7334330-0a94-4ffd-8f1a-e024e8dbb1ee', null, 'Hospitalité', 'La « mise en place », c''est…', '["Placer les clients à table", "Faire l''addition", "Ranger après la fermeture", "Tout préparer avant le service pour être prêt"]', 3, 'Chaque chose à sa place avant le rush : c''est ce qui permet d''être disponible pour le client.', true, 1, 'qcm', null, 'hospitalite'),
('0ff225a8-5102-4020-98b4-aa9fce256f56', null, 'Vrai ou faux', 'On peut offrir un shot à un client en échange d''un avis Google.', '["Vrai", "Faux"]', 1, 'Faux ! Google interdit les avis contre un avantage. On demande, on ne paie jamais un avis.', true, 2, 'tf', null, 'hospitalite'),
('17405e05-5532-4a19-9208-741304f4b7c5', null, 'Service en images', 'Les glaçons se stockent…', '["Avec les bouteilles", "Avec la pelle plantée dedans", "Dans un bac propre, la pelle rangée hors de la glace", "Dans l''évier"]', 2, 'La pelle laissée dans la glace la contamine avec les mains.', true, 2, 'image', '{"img": "a694c8f34a0a"}', 'hospitalite'),
('4466d689-29cb-4ba4-b9dc-b4c022a2da73', null, 'Service en images', 'Le thé marocain est versé de haut pour…', '["Refroidir la théière", "Le spectacle uniquement", "Aller plus vite", "Faire mousser et aérer le thé"]', 3, 'La mousse (le « turban ») est signe d''un thé bien servi.', true, 2, 'image', '{"img": "6066d4499307"}', 'hospitalite'),
('7063ef00-e83a-4804-9cf0-369341292cd2', null, 'Hospitalité', 'Le « paradoxe du service » dit qu''un client dont le problème est bien réglé…', '["Ne revient jamais", "Laisse un mauvais avis", "Demande toujours une remise", "Peut devenir plus fidèle qu''un client sans problème"]', 3, 'Une erreur bien rattrapée crée de la confiance. D''où l''importance de réagir vite et avec le sourire.', true, 2, 'qcm', null, 'hospitalite'),
('91b9ca4c-f9e3-4814-ab58-c57375784699', null, 'Hospitalité', 'Un client attend sa table qui n''est pas prête. Le meilleur réflexe ?', '["Ne rien dire", "L''accueillir au bar avec une attention et lui donner un délai honnête", "Lui dire de revenir plus tard", "Le placer à une table sale"]', 1, 'L''attente bien gérée devient un moment agréable, voire une vente au bar.', true, 2, 'qcm', null, 'hospitalite'),
('a07ce2c5-a91a-4c6b-8edc-e0e8d5f8c017', null, 'Hospitalité', 'Le langage corporel en salle : que faut-il éviter ?', '["Se tenir droit", "Sourire", "Regarder le client dans les yeux", "Bras croisés et regard sur son téléphone"]', 3, 'Le client lit ton attitude avant d''entendre tes mots.', true, 2, 'qcm', null, 'hospitalite'),
('a2c45681-9421-4f59-82c1-1e78f94f520f', null, 'Service', 'De quel côté sert-on traditionnellement les boissons ?', '["Par la gauche", "Peu importe", "Par la droite", "Par le centre de la table"]', 2, 'Les boissons se servent par la droite du client, là où sont les verres.', true, 2, 'qcm', null, 'hospitalite'),
('a77f054f-2d28-43c8-806d-8938593415bd', null, 'Hospitalité', 'Un « moment de vérité » en restauration, c''est…', '["Le moment de l''addition", "Chaque contact où le client se forge une opinion", "La réunion d''équipe", "L''inspection d''hygiène"]', 1, 'Accueil, premier verre, plat, départ : chaque contact compte.', true, 2, 'qcm', null, 'hospitalite'),
('b59160ec-0928-4367-8445-886230093513', null, 'Hospitalité', 'Dans une table, qui sert-on en dernier ?', '["Les femmes", "L''hôte, la personne qui invite", "La personne à ta gauche", "La personne la plus jeune"]', 1, 'Les invités d''abord, l''hôte en dernier : il reçoit, il est servi après ses invités.', true, 2, 'qcm', null, 'hospitalite'),
('b6e9e926-cff8-404e-b590-e6e5d7e20e11', null, 'Hospitalité', 'En stock (bar ou cuisine), la règle FIFO signifie…', '["Ranger par couleur", "Le plus cher d''abord", "Premier entré, premier sorti", "Le plus frais d''abord"]', 2, 'On utilise d''abord ce qui est arrivé en premier : moins de pertes, plus de fraîcheur.', true, 2, 'qcm', null, 'hospitalite'),
('c8a6f23a-b0c0-4207-8620-0250c4447bf1', null, 'Hospitalité', 'Quand on recommande un produit, on évite…', '["De citer un ingrédient", "De sourire", "De forcer la vente", "De parler du goût"]', 2, 'Vendre, c''est conseiller. Un client qui se sent poussé ne revient pas.', true, 2, 'qcm', null, 'hospitalite'),
('339ee98f-bbe9-4487-9be9-e3af427432a5', null, 'Hospitalité', 'La règle du « 10 et 5 » (10 pieds, 5 pieds) en hôtellerie, c''est…', '["10 tables par serveur, 5 par runner", "À 3 mètres un regard et un sourire, à 1,5 mètre un bonjour", "10 minutes d''attente maximum, 5 pour le dessert", "10 % de pourboire, 5 % de remise"]', 1, 'Personne ne passe à côté d''un client sans le reconnaître.', true, 3, 'qcm', null, 'hospitalite'),
('7d3f0e2e-7942-4f30-aa5b-1550b19aeef7', null, 'Hospitalité', 'Pourquoi noter les préférences des habitués (table, boisson, allergies) ?', '["Pour les surveiller", "Pour augmenter leurs prix", "Ce n''est pas utile", "Pour personnaliser chaque visite et créer de la fidélité"]', 3, 'Le client qui se sent reconnu devient ambassadeur du lieu.', true, 3, 'qcm', null, 'hospitalite'),
('8849f5dc-78b6-4234-bf53-ca7f2361e367', null, 'Hospitalité', 'Will Guidara (Eleven Madison Park) a popularisé l''idée d''…', '["Hospitalité déraisonnable : offrir plus que ce qui est attendu", "Augmenter les prix", "Supprimer les serveurs", "Servir plus vite"]', 0, 'Son livre « Unreasonable Hospitality » : des attentions personnalisées qui créent des souvenirs.', true, 3, 'qcm', null, 'hospitalite'),
('b993e01b-6076-407f-acc7-9e812acb31c5', null, 'Hospitalité', 'Selon Danny Meyer (« Setting the Table »), qui doit-on prendre soin en premier ?', '["Les actionnaires", "Les clients uniquement", "Les fournisseurs", "L''équipe"]', 3, 'Une équipe bien traitée traite bien les clients : c''est son « hospitalité éclairée ».', true, 3, 'qcm', null, 'hospitalite'),
('71c372dc-50a6-4c39-bc16-ce894962c520', null, 'Sécurité', 'Une bagarre éclate. Que fais-tu ?', '["Je n''interviens pas seul, j''alerte le responsable et j''éloigne les autres clients", "Je m''interpose seul", "Je continue mon service", "Je filme"]', 0, 'Ta sécurité d''abord. On agit à plusieurs et on appelle la police si besoin.', true, 1, 'qcm', null, 'securite'),
('7f1efa5d-52c4-4829-a93e-976b7f9dd2ec', null, 'Sécurité', 'Les issues de secours doivent être…', '["Utilisées pour stocker les caisses", "Toujours dégagées et accessibles", "Masquées par la déco", "Fermées à clé pendant le service"]', 1, 'Une issue encombrée est une faute rouge dans la charte.', true, 1, 'qcm', null, 'securite'),
('84b5b870-7c7e-4f71-9d1d-148b895dd314', null, 'Sécurité', 'Un client visiblement ivre demande un autre verre.', '["Je refuse poliment, je propose de l''eau ou un taxi et je préviens le responsable", "Je le sers, c''est un client", "Je l''ignore", "Je lui dis qu''il a trop bu devant tout le monde"]', 0, 'Servir un client ivre est une faute rouge. La politesse évite l''escalade.', true, 1, 'scene', null, 'securite'),
('a0ac1034-c78e-49ae-bfbe-3b8cd9c6826a', null, 'Sécurité', 'On peut utiliser un extincteur à eau sur un feu électrique.', '["Vrai", "Faux"]', 1, 'Faux ! Sur un feu électrique, on utilise un extincteur à CO2.', true, 1, 'tf', null, 'securite'),
('f58d9b6e-1947-4e10-9a34-c4343240f764', null, 'Sécurité en images', 'Où doit rester cet extincteur ?', '["Dans la réserve", "Derrière une porte fermée", "À sa place, visible et accessible", "Peu importe"]', 2, 'En cas de feu, chaque seconde compte : il doit être à portée de main.', true, 1, 'image', '{"img": "59efa47fa15b"}', 'securite'),
('15c146cf-c724-4a79-b057-db5664340fda', null, 'Sécurité', 'Un client devient agressif à l''entrée parce qu''il n''a pas de réservation.', '["Je reste calme, voix posée, j''explique et j''appelle le responsable", "Je le laisse entrer pour éviter le problème", "Je le pousse dehors", "Je hausse le ton pour me faire respecter"]', 0, 'Le calme désamorce. On ne répond jamais à une provocation.', true, 2, 'scene', null, 'securite'),
('1d3cc6b6-ac1c-44be-a9bc-6e11de1c46a2', null, 'Sécurité', 'En cas d''évacuation, le bon réflexe :', '["Guider les clients vers les sorties, sans courir, jusqu''au point de rassemblement", "Récupérer la caisse d''abord", "Finir le service en cours", "Prendre l''ascenseur"]', 0, 'Les clients d''abord, puis on vérifie que personne ne manque.', true, 2, 'qcm', null, 'securite'),
('31b7d2ea-efcf-4ede-bc9a-ce0601f75289', null, 'Sécurité', 'Au Maroc, quel numéro appelle les pompiers (protection civile) ?', '["19", "177", "15", "112"]', 2, '15 pour les pompiers et secours, 19 pour la police en ville, 177 pour la gendarmerie.', true, 2, 'qcm', null, 'securite'),
('a509224e-96d0-429a-a659-f7de54529822', null, 'Sécurité', 'Un client oublie son téléphone. Tu…', '["Le mets au bar sans rien dire", "Le gardes jusqu''à son retour", "Le remets au responsable et on le note au registre des objets trouvés", "Le laisses sur la table"]', 2, 'Traçabilité : on note l''heure, la table, et qui l''a remis.', true, 2, 'qcm', null, 'securite'),
('98e53163-ebe1-4784-9bba-96fe244536f2', null, 'Sécurité', 'Tu dois refuser l''entrée à un groupe. Ta phrase ?', '["Je suis désolé, ce soir nous ne pouvons pas vous accueillir. Je vous souhaite une bonne soirée.", "Vous n''avez pas le style.", "Revenez quand vous serez mieux habillés.", "Vous ne rentrez pas, c''est tout."]', 0, 'On peut refuser sans humilier. La réputation du lieu se joue aussi à la porte.', true, 3, 'scene', null, 'securite'),
('ba7d8ab3-fb2c-4884-be25-3db3a04ad39b', null, 'Sécurité', 'L''agent de sécurité est souvent la première personne que le client voit.', '["Vrai", "Faux"]', 0, 'Vrai ! Un bonjour et un sourire à la porte, c''est le début de l''expérience.', true, 3, 'tf', null, 'securite'),
('0c40b22f-f9d3-4707-8fe5-5d86c0083a2a', null, 'Cross-sell', 'Le cross-sell, c''est…', '["Vendre plus cher le même produit", "Faire une remise", "Changer la commande du client", "Proposer un produit complémentaire"]', 3, 'Cross-sell = produit complémentaire (une entrée, un dessert, un accord). Upsell = version supérieure.', true, 1, 'qcm', null, 'vente'),
('2cdf18a2-1a81-4215-9b34-f93884980a8e', null, 'Gentillesse', 'Le client : « C''est notre anniversaire de mariage ce soir. »', '["Félicitations ! Je vais faire en sorte que ce soit une soirée inoubliable.", "Ça fait combien d''années ?", "Vous voulez l''addition ?", "Ah d''accord."]', 0, 'Un moment spécial à repérer : on prévient le manager pour une attention (bougie, dessert, mot).', true, 1, 'scene', null, 'vente'),
('3cc0ede8-05a2-4a19-a9e9-e343cd6b6d06', null, 'Gentillesse', 'Le client : « Surprenez-moi ! »', '["Je ne sais pas, regardez la carte", "Avec plaisir ! Plutôt frais et fruité, ou intense et épicé ?", "Un mojito alors", "Je vous mets le plus cher"]', 1, 'Une question de goût suffit pour viser juste. Et le client se sent écouté.', true, 1, 'scene', null, 'vente'),
('c5794fbd-7208-4fad-aee3-d77b6fb5c2e0', null, 'Avis Google', 'Le client : « C''était parfait, merci ! On reviendra. »', '["Vous devez mettre un avis avant de partir.", "Ok merci, bonne soirée.", "Laissez-nous 5 étoiles svp !", "Ça nous touche ! Si vous avez une minute, un avis sur Google aide beaucoup notre équipe."]', 3, 'Le bon moment, c''est quand le client exprime lui-même sa satisfaction. On demande, sans forcer.', true, 1, 'scene', null, 'vente'),
('18052e8f-aa71-4673-a395-853de041b8a2', null, 'Storytelling', 'Que faut-il éviter quand on raconte un produit ?', '["Parler du goût", "Parler de l''origine d''un ingrédient", "Sourire", "Inventer une histoire fausse"]', 3, 'Jamais inventer : un client curieux vérifie, et la confiance est perdue.', true, 2, 'qcm', null, 'vente'),
('19741430-5c1e-4411-83e1-f0eb8fb4241e', null, 'Upsell', 'Quelle phrase vend le mieux ?', '["Vous voulez autre chose ?", "Je vous conseille notre cocktail signature, il est parfait avec ce plat", "On a aussi des desserts", "C''est tout ?"]', 1, 'Une recommandation précise et personnelle vend mieux qu''une question fermée.', true, 2, 'qcm', null, 'vente'),
('1c0d6978-fa2e-498a-9ea3-d66dfe35f645', null, 'Gentillesse', 'Le client hésite devant le prix du Pommard.', '["Prenez-le, vous ne le regretterez pas", "Je vous propose aussi le Bourgogne Pinot Noir, même cépage, très élégant et plus accessible", "Il n''y a rien de moins cher", "Le prix est indiqué sur la carte"]', 1, 'On guide sans gêner : une alternative dans le même style, sans jamais juger le budget.', true, 2, 'scene', null, 'vente'),
('32ae3bc8-746a-4ede-a2e0-bb1e3d01bd4f', null, 'Storytelling', 'Une bonne histoire de cocktail au service dure environ…', '["5 minutes", "2 minutes", "10 à 20 secondes", "Le temps de toute la préparation"]', 2, 'Court, une image forte, un détail sur un ingrédient. Le client doit avoir envie d''en parler à sa table.', true, 2, 'qcm', null, 'vente'),
('454ca6a2-6424-40c1-b710-e715a97d0700', null, 'Vente', 'Un client demande « qu''est-ce que vous me conseillez ? ». Tu réponds…', '["Le moins cher", "Vous aimez plutôt frais et acidulé ou rond et boisé ?", "Tout est bon", "Ça dépend de vous"]', 1, 'Une question de goût permet de recommander juste et donne confiance.', true, 2, 'qcm', null, 'vente'),
('4ae2a6a5-d41e-408e-af41-3a1b2f28d8cd', null, 'Vente', 'Un client commande « une bière ». Tu réponds…', '["D''accord", "Pression ou bouteille ? On a aussi une bière artisanale très fraîche", "On n''a que ça", "Laquelle ?"]', 1, 'Préciser et proposer mieux en une phrase : c''est vendre sans forcer.', true, 2, 'qcm', null, 'vente'),
('6c8b8c09-515b-4592-b0ef-0c56987b9f14', null, 'Avis Google', 'Le client : « Comment je vous trouve sur Google ? »', '["Je vous montre : le plus simple, c''est ce QR code, ça prend 30 secondes", "Cherchez sur internet", "Je ne sais pas", "Sur Facebook plutôt"]', 0, 'Toujours avoir le lien ou le QR code sous la main : on rend le geste facile.', true, 2, 'scene', null, 'vente'),
('75bd7c79-a7d9-411e-956b-ce0566336428', null, 'Storytelling', 'Le storytelling d''un cocktail sert surtout à…', '["Faire attendre le client", "Montrer qu''on connaît la recette", "Donner de la valeur et justifier le prix", "Remplir le silence"]', 2, 'Une histoire courte transforme une boisson en expérience : le client paie pour ça.', true, 2, 'qcm', null, 'vente'),
('a5c7a667-af5c-4c8b-9203-8e74904dd71e', 'zz', 'Cross-sell', 'Avec le Fondant Amlou, quel cocktail recommander pour prolonger le thème amlou-argan ?', '["Margarita", "Apérol Spritz", "Moscow Mule", "Berberliner"]', 3, 'Le Berberliner reprend l''argan et l''amlou : accord parfait avec le Fondant.', true, 2, 'qcm', null, 'vente'),
('a9689b67-d428-4719-9d69-909c4c3ceee8', null, 'Upsell', 'Un client commande un gin tonic. Quel est le meilleur upsell ?', '["Ne rien proposer", "Lui proposer un gin premium dans le même cocktail", "Lui proposer un deuxième verre tout de suite", "Lui proposer une bouteille d''eau"]', 1, 'Monter en gamme sur le même produit : le client garde son choix, le ticket augmente.', true, 2, 'qcm', null, 'vente'),
('ab2fdc06-9ca9-4bda-9412-42d265aaf11e', null, 'Gentillesse', 'Un touriste demande : « What is ras el hanout? »', '["I don''t know", "It''s a cheese", "It''s very spicy, don''t take it", "It''s a Moroccan spice blend, warm and fragrant. It literally means head of the shop."]', 3, 'Ras el hanout signifie « la tête de la boutique » : le meilleur mélange de l''épicier.', true, 2, 'scene', null, 'vente'),
('bd5b9403-862e-4054-803b-781289951077', null, 'Cross-sell', 'Une table finit son plat principal. Le meilleur moment pour proposer le dessert ?', '["Au moment de la commande des entrées", "Seulement si on te le demande", "Avec l''addition", "Quand tu débarrasses les assiettes"]', 3, 'Au débarrassage, l''attention du client est disponible et la table n''a pas encore décidé de partir.', true, 2, 'qcm', null, 'vente'),
('d50ece4d-fbfc-4f2b-af48-394f1e8d0650', null, 'Vente', 'Combien d''options faut-il idéalement proposer à un client qui hésite ?', '["Cinq", "Toute la carte", "Deux ou trois", "Une seule"]', 2, 'Trop de choix bloque la décision. Deux ou trois options guidées font vendre.', true, 2, 'qcm', null, 'vente'),
('db53d6e4-81ff-4a4c-9706-207c533de99b', null, 'Avis Google', 'Le client a attendu son plat 40 minutes et soupire en payant.', '["On s''excuse sincèrement, on prévient le manager, et on ne demande pas d''avis ce soir", "On ne dit rien", "On lui explique que la cuisine était débordée et que ce n''est pas notre faute", "On lui demande un avis Google quand même"]', 0, 'On répare d''abord. Un client mécontent bien rattrapé peut devenir ton meilleur ambassadeur.', true, 2, 'scene', null, 'vente'),
('ed59668d-ab51-4964-b5f6-4ccb4f044027', 'zz', 'Cross-sell', 'Un client hésite après le plat. Quel dessert raconte le mieux l''identité marocaine de Zama ?', '["Une glace vanille simple", "Le Fondant Amlou (beurre d''amande et argan)", "Un café", "L''addition"]', 1, 'Le Fondant Amlou : cœur coulant amande et argan, glace vanille. Une histoire marocaine à raconter.', true, 2, 'qcm', null, 'vente'),
('ef31b00b-07f3-4e36-b73e-26a321f9729e', 'zz', 'Upsell', 'Un client commande un Negroni classique (140 DH). Quelle montée en gamme proposer ?', '["Un Apérol Spritz", "Rien", "Une bière", "Un Mezcal Negroni (180 DH), plus fumé"]', 3, 'Même famille, profil plus fumé : le client garde son goût, le ticket monte.', true, 2, 'qcm', null, 'vente'),
('f030cf83-4c23-40d8-96e7-396fb32f2583', 'zz', 'Upsell', 'Un client demande un gin tonic avec Beefeater. Quel gin proposer en premium ?', '["Havana 7 ans", "Absolut", "Hendrick''s ou Palmaráe 1er Cru", "Ricard"]', 2, 'Beefeater 100, Hendrick''s 140, Palmaráe 1er Cru 160 : la montée en gamme naturelle.', true, 2, 'qcm', null, 'vente'),
('f502bf5b-bb24-40a0-a63d-f17598985206', 'zz', 'Upsell', 'Une table fête un anniversaire. Quelle bouteille proposer en priorité ?', '["Une bière Casablanca", "Mumm Cordon Rouge ou Ruinart Blanc de Blancs", "Une eau Castalie", "Un thé à la menthe"]', 1, 'Zama est un lieu de « Celebration » : le champagne s''impose pour un moment à fêter.', true, 2, 'qcm', null, 'vente'),
('fefca1a9-1dc5-4aa6-a1ad-ce2f43a58d6b', 'baro', 'Cross-sell Baro', 'Une table commande des plats à partager. Quelle phrase vend le mieux ?', '["C''est tout ?", "Je vous conseille aussi nos cigars de Lalla au poulet et gingembre, c''est la recette de nos grands-mères", "On a aussi d''autres plats", "Autre chose ?"]', 1, 'Un plat précis, une histoire courte : c''est ça le cross-sell.', true, 2, 'qcm', null, 'vente'),
('126e514b-1561-4543-bb35-e52d30b7c961', null, 'Gentillesse', 'Le client : « C''est épicé, le Naughty Tequila ? »', '["Oui, c''est intense : piment, poivrons et harissa. Si vous aimez le feu, foncez, sinon je vous conseille le Liquid Sunshine", "Un peu", "Je ne sais pas, je ne l''ai jamais goûté", "Non pas du tout"]', 0, 'L''honnêteté avant tout : un client prévenu est un client content.', true, 3, 'scene', null, 'vente'),
('4c8faff1-3132-4487-a3aa-075a20d48139', null, 'Avis Google', 'Le client veut citer ton prénom dans son avis. Tu dis…', '["Écrivez que le service était parfait", "Mettez plutôt le nom du manager", "Non, ce n''est pas la peine", "Avec plaisir ! Merci, ça me touche beaucoup, et toute l''équipe sera ravie."]', 3, 'Un avis qui cite ton prénom te rapporte +100 pts une fois validé. Et ça fait plaisir à toute l''équipe.', true, 3, 'scene', null, 'vente'),
('3114099d-f68e-4468-a409-17d3d395871a', null, 'Vins en images', 'Le Chardonnay, c''est…', '["Un type de bouchon", "Un cépage rouge", "Une région", "Un cépage blanc"]', 3, 'Le Chardonnay donne les grands blancs de Bourgogne.', true, 1, 'image', '{"img": "60e656011160"}', 'vins'),
('33c0506f-1887-4d9f-9846-d9dd336db9e8', null, 'Vins', 'Quand tu sers une bouteille, à qui fais-tu goûter le vin en premier ?', '["À personne", "À la personne à ta droite", "À la plus âgée", "À la personne qui a commandé le vin"]', 3, 'L''hôte goûte, valide, puis tu sers les invités et l''hôte en dernier.', true, 1, 'qcm', null, 'vins'),
('48d8d282-679a-4b80-bff7-f506e0d907f4', null, 'Vins', 'Le rosé est fait à partir de…', '["Un mélange de vin blanc et de vin rouge", "Raisins rouges avec une macération courte", "Raisins blancs uniquement", "Raisins roses"]', 1, 'Le jus de raisin est blanc : c''est la peau des raisins rouges, laissée peu de temps, qui donne la couleur rose.', true, 1, 'qcm', null, 'vins'),
('7f2bb733-dcd7-4f00-bde4-0bc1e6fc11b5', null, 'Vins', 'Le vin « gris » marocain, comme l''Ait Souala Gris, c''est…', '["Un vin rouge léger", "Un vin pétillant", "Un rosé très pâle", "Un vin blanc vieilli"]', 2, 'Le gris est un rosé très clair, spécialité marocaine. Ici Grenache et Cinsault.', true, 1, 'qcm', null, 'vins'),
('9954d7a0-4164-49ca-9435-c5b0edb6974d', null, 'Vins', 'Le Pommard de notre carte est un vin…', '["Rosé", "Blanc", "Effervescent", "Rouge"]', 3, 'Pommard (Bourgogne) est une appellation uniquement en rouge, 100 % Pinot Noir.', true, 1, 'qcm', null, 'vins'),
('d3919d46-229b-4229-9d64-70e8fe8a5492', null, 'Vins', 'Quel vin se sert le plus frais ?', '["Le vin blanc boisé", "Le vin rouge", "Tous à la même température", "Le champagne"]', 3, 'Champagne 6 à 8 °C, blanc 8 à 12 °C, rouge 15 à 18 °C.', true, 1, 'qcm', null, 'vins'),
('ef30048b-1082-4484-958f-2b3d1baea8d8', null, 'Vins en images', 'Comment s''appelle cet outil ?', '["Un tire-bouchon limonadier", "Un couteau d''office", "Un tire-bouchon à levier", "Un décapsuleur seul"]', 0, 'Le limonadier : lame pour la capsule, mèche et levier. L''outil du serveur.', true, 1, 'image', '{"img": "f4dc545c658d"}', 'vins'),
('f5df7f66-67d0-4497-b726-4d0f4d7ae60c', null, 'Vins', 'Jusqu''où remplit-on un verre de vin rouge ?', '["À ras bord", "Environ un tiers", "À moitié minimum", "Aux trois quarts"]', 1, 'Un tiers laisse la place au vin de respirer et au client de le faire tourner.', true, 1, 'qcm', null, 'vins'),
('0f333175-f30c-464c-b1b2-fd3c5e8a7b74', null, 'Accords mets et vins', 'Pour un poisson au beurre blanc (Pêche Atlantique), quel vin ?', '["Un rouge tannique", "Petit Chablis ou Chardonnay", "Un rosé sucré", "Une bière"]', 1, 'Un Chardonnay frais équilibre le gras du beurre sans écraser le poisson.', true, 2, 'qcm', null, 'vins'),
('40374100-9d02-405f-ab1c-522abc8ab221', 'zz', 'Vins', 'Un client veut un vin rouge marocain. Que proposer ?', '["Pommard", "Rioja Marqués de Cáceres", "Château Roslane 1er Cru ou CB Signature", "Chianti"]', 2, 'Roslane (Meknès) et CB Signature, S de Siroua, Médaillon (Benslimane) sont marocains.', true, 2, 'qcm', null, 'vins'),
('5017a4ad-c45f-48a9-a1c3-a2b42ec4c4b4', null, 'Accords mets et vins', 'Pour une viande de bœuf épicée (Le Tigre qui Pleure / qui Danse), quel vin ?', '["Le Côte du Rhône Guigal (Syrah, Grenache)", "Un vin blanc léger", "Du prosecco", "Le Pinot Grigio"]', 0, 'Le côté épicé et fruité du Rhône accompagne bien bœuf et épices.', true, 2, 'qcm', null, 'vins'),
('63925033-2905-4c21-96be-78b2f03a5d8b', null, 'Vins en images', 'Accord classique avec les huîtres ?', '["Un rouge tannique", "Un porto", "Un vin doux", "Un blanc sec et iodé (Muscadet, Chablis)"]', 3, 'L''iode appelle un blanc vif et minéral.', true, 2, 'image', '{"img": "1c46a1889aa2"}', 'vins'),
('6d3f8eec-87be-43f1-83ba-cf705ecf76c9', null, 'Vins', 'Le Viognier (Ait Souala blanc) est un cépage…', '["Très acide et minéral", "Aromatique, fleurs blanches et abricot", "Rouge et tannique", "Neutre"]', 1, 'Né dans la Vallée du Rhône (Condrieu), il donne des blancs ronds et parfumés.', true, 2, 'qcm', null, 'vins'),
('762111cb-e291-4883-96e1-9897486c0060', null, 'Vins', 'Quels deux vins de notre carte viennent de la famille Perrin ?', '["Médaillon et Roslane", "Pommard et Petit Chablis", "Studio by Miraval et La Vieille Ferme", "Chianti et Rioja"]', 2, 'Belle histoire à raconter : une même grande famille de la Vallée du Rhône derrière deux rosés.', true, 2, 'qcm', null, 'vins'),
('81474b3a-9de4-4152-ab3b-300c3fe95bdc', null, 'Vins', 'Le Chianti vient de quelle région ?', '["La Rioja", "La Bourgogne", "La Toscane", "Le Piémont"]', 2, 'Toscane, cépage principal Sangiovese.', true, 2, 'qcm', null, 'vins'),
('94840046-6944-454a-9012-f07c114aad98', 'zz', 'Vins', 'Quel rosé de la carte vient du Château Miraval en Provence ?', '["Ait Souala Gris", "CB Signature", "Studio by Miraval", "La Vieille Ferme"]', 2, 'Studio by Miraval, 550 DH.', true, 2, 'qcm', null, 'vins'),
